#!/usr/bin/env node
// RF-B4, RF-B6: post-processes the TypeScript that ts-rs exported into
// packages/protocol-ts/src/generated/ (called by `just gen`, before Prettier):
// - fails, without writing anything, if a generated file contains `bigint` (a 64-bit or wider
//   integer slipped into an exported type; JavaScript loses precision above 2^53);
// - prepends the "generated, do not edit" header to every file (idempotent);
// - writes the barrel src/index.ts with one `export type *` per generated file, sorted.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export const HEADER =
  '// Generated by `just gen` from crates/protocol (ts-rs). Do not edit: change the Rust types and run `just gen`.\n';
const BIGINT = /\bbigint\b/;

/**
 * @param {string} srcDir the package's `src` directory (contains `generated/`)
 * @returns {{ files: string[], problems: string[] }}
 */
export function finalizeProtocolTs(srcDir) {
  const generatedDir = path.join(srcDir, 'generated');
  if (!existsSync(generatedDir)) {
    return { files: [], problems: [`${generatedDir}: directory not found (did ts-rs run?)`] };
  }
  const files = readdirSync(generatedDir)
    .filter((name) => name.endsWith('.ts'))
    .sort();
  /** @type {string[]} */
  const problems = [];
  if (files.length === 0) problems.push(`${generatedDir}: no .ts files (did ts-rs run?)`);
  const sources = new Map();
  for (const name of files) {
    const source = readFileSync(path.join(generatedDir, name), 'utf8');
    if (BIGINT.test(source)) {
      problems.push(
        `generated/${name}: contains \`bigint\` (a 64-bit or wider integer in an exported type; see RF-B4)`,
      );
    }
    sources.set(name, source);
  }
  if (problems.length > 0) return { files, problems };

  for (const [name, source] of sources) {
    if (!source.startsWith(HEADER)) writeFileSync(path.join(generatedDir, name), HEADER + source);
  }
  const barrel =
    HEADER +
    files
      .map((name) => `export type * from './generated/${name.replace(/\.ts$/, '.js')}';\n`)
      .join('');
  writeFileSync(path.join(srcDir, 'index.ts'), barrel);
  return { files, problems };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const srcDir = path.resolve(process.argv[2] ?? path.join(ROOT, 'packages/protocol-ts/src'));
  const { files, problems } = finalizeProtocolTs(srcDir);
  if (problems.length > 0) {
    console.error(`gen-protocol-ts: ${problems.length} problem(s)`);
    for (const p of problems) console.error(`  ${p}`);
    process.exit(1);
  }
  console.log(`gen-protocol-ts: ${files.length} file(s)`);
}
